-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 1: Introdução a computadores, internet e Java — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('fe6c03fe-0648-5eb6-a638-e6d7ba82c167', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Qual componente realiza operações aritméticas e lógicas?', '["Impressora.","Disco.","Monitor.","ULA.","Teclado."]'::jsonb, 3, 'A unidade aritmética e lógica integra o processamento da CPU.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.2, páginas 38–39 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8ed266c8-c92d-5c74-863a-e02d560ea592', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Após desligar a alimentação, qual memória normalmente perde seu conteúdo?', '["RAM volátil.","Disco rígido.","Memória flash.","SSD.","Mídia óptica."]'::jsonb, 0, 'Volatilidade significa depender de alimentação para manter os dados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.2, páginas 38–39 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f6987168-02e6-5f6a-b01f-618f5ce43570', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Qual sequência cresce em nível de organização dos dados?', '["Bit, caractere, campo, registro.","Bit, registro, caractere, campo.","Campo, bit, registro, caractere.","Registro, bit, campo, caractere.","Caractere, registro, bit, campo."]'::jsonb, 0, 'Campos reúnem caracteres; registros agrupam campos relacionados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.3, páginas 40–41 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fc9d9015-cf47-550a-8848-f43dc58f10e2', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Fácil', 'Qual programa traduz linguagem assembly em código de máquina?', '["Navegador.","Assembler.","Depurador gráfico.","Editor.","Carregador de páginas web."]'::jsonb, 1, 'O assembler traduz instruções simbólicas de montagem.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.4, páginas 42 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('518dce47-9a67-5be2-8bd2-27b28746e184', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Fácil', 'Uma linguagem de alto nível distingue-se por:', '["Ser idêntica ao assembly.","Abstrair detalhes da máquina.","Dispensar tradução em qualquer ambiente.","Ser composta apenas de bits.","Descrever somente circuitos."]'::jsonb, 1, 'Abstração facilita expressar soluções sem escrever instruções de máquina diretamente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.4, páginas 42 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8df0aeaa-f493-52d6-ab1d-f013b6f2516a', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Fácil', 'Na orientação a objetos, uma classe descreve principalmente:', '["Uma conexão de rede.","Um endereço físico obrigatório.","Um tipo de objeto e seus recursos.","Uma única execução de método.","Um arquivo de resultados."]'::jsonb, 2, 'Objetos são instâncias das classes correspondentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3de6e480-2a8d-57b2-bb7c-ea0b1c0ecbe9', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Fácil', 'Criar um objeto de uma classe é chamado de:', '["Importação.","Sobrescrita.","Compilação JIT.","Instanciação.","Serialização obrigatória."]'::jsonb, 3, 'Instanciar produz um objeto, não apenas uma descrição de tipo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2be27c29-eec4-5cc0-81a9-4ab6bbe1d7a9', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Fácil', 'Os dados próprios de cada objeto são representados tipicamente por:', '["Variáveis de instância.","Arquivos .class exclusivos.","Pacotes.","Comentários.","Parâmetros de compilação."]'::jsonb, 0, 'Cada instância possui seu estado conforme os campos declarados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('18cbd422-eeee-50eb-bd6f-f5b43aadd588', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Fácil', 'Um método representa principalmente:', '["Um caractere.","Um tipo de arquivo.","Uma operação ou comportamento.","Um dispositivo físico.","Uma senha."]'::jsonb, 2, 'Métodos implementam ações dos objetos ou das classes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('48b651a2-0942-582f-b2a2-eb2940779fb2', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Fácil', 'Ocultar a representação interna por uma interface favorece:', '["Dependência de campos públicos.","Ausência de validação.","Duplicação de classes.","Acesso irrestrito.","Encapsulamento."]'::jsonb, 4, 'Clientes passam a depender do contrato, não dos detalhes internos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fc1ee99d-918e-5fe1-9813-2a3aeac41f22', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Fácil', 'Reutilizar comportamento de uma superclasse relaciona-se à:', '["Coleta de lixo.","Criptografia.","Leitura de teclado.","Herança.","Tokenização."]'::jsonb, 3, 'Herança define uma especialização a partir de uma classe existente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1b02f9df-8cb4-5a26-824f-dad63db154e6', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Fácil', 'Uma interface especifica principalmente:', '["Uma cópia física da classe.","Uma senha de usuário.","Um contrato de operações.","Um objeto necessariamente instanciável.","Um endereço de memória."]'::jsonb, 2, 'Classes diferentes podem oferecer o comportamento exigido pelo contrato.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a0bcfa21-01cd-5bed-8c4d-34d28363c0a5', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Fácil', 'A UML é empregada para:', '["Gerenciar coleta de lixo.","Compilar assembly.","Substituir a JVM.","Modelar aspectos de sistemas.","Executar bytecode."]'::jsonb, 3, 'Diagramas UML ajudam a representar estrutura e comportamento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.5, páginas 43–44 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5230799f-1ab6-5bf9-9635-588bf33a863f', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Fácil', 'Qual é um papel de um sistema operacional?', '["Definir apenas classes Java.","Substituir todos os compiladores.","Escrever todo código de negócio.","Eliminar a memória.","Gerenciar recursos e execução de programas."]'::jsonb, 4, 'O sistema operacional administra recursos compartilhados da máquina.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.6, páginas 45 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b30b5d7-7a19-5c4d-b319-eb4ed7d312ac', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Fácil', 'O compilador Java produz normalmente:', '["Exclusivamente código SQL.","Somente páginas HTML.","Bytecode em arquivos .class.","Somente código-fonte .java.","Apenas diagramas UML."]'::jsonb, 2, 'Bytecode é executado pelo ambiente da máquina virtual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.8, páginas 48–50 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e005363-2389-52d9-803a-3ff40a2f4293', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Fácil', 'Qual ferramenta compila código-fonte Java?', '["jar como depurador.","Um navegador.","java como editor.","javadoc como compilador.","javac."]'::jsonb, 4, 'A compilação verifica o fonte e produz arquivos de classe.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.9, páginas 48–50 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e7c748a1-6759-55eb-b223-235dfbf4bcb3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Fácil', 'Qual componente executa bytecode Java?', '["Scanner de entrada.","JVM.","Somente o editor.","Gerenciador de layout.","Assembler textual."]'::jsonb, 1, 'A JVM fornece o ambiente de execução do bytecode.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.9, páginas 48–50 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b46e427d-2572-587a-9636-12a36ed9e2ec', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Fácil', 'A compilação JIT busca:', '["Traduzir código em execução para código nativo.","Substituir o sistema operacional.","Converter toda variável em texto.","Criar interfaces gráficas.","Eliminar a compilação do fonte."]'::jsonb, 0, 'JIT pode otimizar trechos durante a execução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.9, páginas 48–50 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f5e918eb-5f15-51c6-b3a1-5799df3edd35', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Fácil', 'Internet e Web são conceitos idênticos?', '["Sim, ambos são navegadores.","Não; a Web utiliza a infraestrutura da Internet.","Não; a Web dispensa redes.","Sim, ambos são HTML.","Sim, ambos são Java."]'::jsonb, 1, 'A Internet suporta serviços além da Web.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.11, páginas 55–56 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('71d35043-11fd-55d9-ab88-68aa6f7aba53', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Fácil', 'Código-fonte aberto significa necessariamente ausência de licença?', '["Não; o fonte permanece sempre oculto.","Sim, inclusive para marcas registradas.","Sim, todo uso é irrestrito.","Sim, desaparecem direitos autorais.","Não; o uso continua sujeito à licença aplicável."]'::jsonb, 4, 'Disponibilidade do fonte e condições de licenciamento são aspectos diferentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 1, seção 1.12, páginas 57 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

